def transform(grid):
    from collections import Counter, defaultdict
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    colored = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                colored[(r, c)] = grid[r][c]
    by_color = defaultdict(list)
    for (r, c), v in colored.items():
        by_color[v].append((r, c))

    def blocked(r, c, color):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if (rr, cc) in colored and colored[(rr, cc)] != color:
                    return True
        return False

    for color, cells in by_color.items():
        for keyfn in (lambda r, c: r - c, lambda r, c: r + c):
            groups = defaultdict(list)
            for r, c in cells:
                groups[keyfn(r, c)].append((r, c))
            for key, grp in groups.items():
                if len(grp) < 2:
                    continue
                grp.sort()
                (r0, c0), (r1, c1) = grp[0], grp[-1]
                dr = (r1 > r0) - (r1 < r0)
                dc = (c1 > c0) - (c1 < c0)
                if dr == 0 and dc == 0:
                    continue
                # forward from the far end
                r, c = r1 + dr, c1 + dc
                while 0 <= r < H and 0 <= c < W:
                    if (r, c) in colored or blocked(r, c, color):
                        break
                    out[r][c] = color
                    r += dr; c += dc
                # backward from the near end
                r, c = r0 - dr, c0 - dc
                while 0 <= r < H and 0 <= c < W:
                    if (r, c) in colored or blocked(r, c, color):
                        break
                    out[r][c] = color
                    r -= dr; c -= dc
    return out
